contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public {
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(
            (amount <= balBefore && !reverted && balAfter + amount == balBefore && supplyBefore >= amount && supplyAfter + amount == supplyBefore)
            ||
            (amount > balBefore && reverted && balAfter == balBefore && supplyAfter == supplyBefore)
        );
    }
}

